SET NOCOUNT ON;
SET XACT_ABORT ON;
IF EXISTS (SELECT 1 FROM ihc.Assay)
BEGIN
    PRINT N'ihc.Assay already has rows; the catalog seed was skipped.';
    RETURN;
END
BEGIN TRANSACTION;
SET IDENTITY_INSERT ihc.Assay ON;

SET IDENTITY_INSERT ihc.Assay OFF;

UPDATE a SET Status = N'DUPLICATE', DuplicateOfAssayId = s.DuplicateOf
FROM ihc.Assay AS a JOIN (VALUES (3, 2), (4, 2), (49, 48), (152, 139), (175, 174), (660, 658), (662, 658), (709, 708), (742, 740)) AS s (AssayId, DuplicateOf) ON s.AssayId = a.AssayId;







